INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ISL_ALI_QURAN','ENT_ISL_ALI','SRC_QURAN','The Qur’an','Quran 5:55','And not only were several Arab tribes in the neighbourhood of Mecca converts to the Christian faith, but on two occasions Muhammad had travelled with his uncle, Abu Talib, as far as Bostra, where he must have had opportunities of learning the general outlines of Oriental Christian doctrine, and perhaps of witnessing the ceremonial of their worship.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ARA_MANAT_QURAN','ENT_ARA_MANAT','SRC_QURAN','The Qur’an','Quran 53:20:','Do you see Al-Lat and Al-Ozza,6 And Manat the third idol besides?7 What? shall ye have male progeny and God female? This were indeed an unfair partition! These are mere names: ye and your fathers named them thus: God hath not sent down any warranty in their regard. A mere conceit and their own impulses do they follow. Yet hath "the guidance" from their Lord come to them.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_ALLAH_QURAN','ENT_ISL_ALLAH','SRC_QURAN','The Qur’an','The Qur’an','To Moslems he is, of course, the prophet par excellence, and the Koran is regarded by the orthodox as nothing less than the eternal utterance of Allah. The eulogy pronounced by Carlyle on Muhammed in Heroes and Hero Worship will probably be endorsed by not a few at the present day. The extreme contrary opinion, which in a fresh form has recently been revived1 by an able writer, is hardly likely to find much lasting support.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_FATIMA_QURAN','ENT_ISL_FATIMA','SRC_QURAN','The Qur’an','Quran 33:33','leaving only Fatima. 26 This may refer to the charge of adultery said by the Rabbins to have been brought by Korah against Moses. Comp. Tr. Sanhedrin, fol. 110a. and Numbers xii. 1. The verse is said to have been revealed on account of aspersions thrown on Muhammad for unfairly dividing spoils, whereupon he said, "God be merciful to my brother Moses.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_HARUN_QURAN','ENT_ISL_HARUN','SRC_QURAN','The Qur’an','The Qur’an','in Jobum) of versions, "vel sensum e sensu, vel ex utroque commixtum, et medie temperatum genus translationis." The proper names are usually given as in our Scriptures: the English reader would not easily recognise Noah as Nûh, Lot as Lût, Moses as Musa, Abraham as Ibrahym, Pharaoh as Firaun, Aaron as Harun, Jesus as Isa, John as Yahia, etc.; and it has been thought best to give different renderings of the same constantly recu','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_HARUT_QURAN','ENT_ISL_HARUT','SRC_QURAN','The Qur’an','The Qur’an','Sorcery did they teach to men, and what had been revealed to the two angels, Harut and Marut, at Babel. Yet no man did these two teach until they had said, "We are only a temptation. Be not then an unbeliever." From these two did men learn how to cause division between man and wife: but unless by leave of God, no man did they harm thereby.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_IBRAHIM_QURAN','ENT_ISL_IBRAHIM','SRC_QURAN','The Qur’an','The Qur’an','square, said to contain the sacred stone on which Ibrahim stood when he built the Caaba. Burckhardt. Lieut. Burton (Pilgrimage, iii. 336) says that as the Arab tradition speaks clearly and consistently as to the fact of Abraham having visited Mecca to build the Caaba, it may be considered an open question. Thus also Dr. G. W. Freytag (Einl.). 35 The Koran. 36 Or, they are smitten with. Sale. S''etendra comme une tente. Kas.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_ISA_QURAN','ENT_ISL_ISA','SRC_QURAN','The Qur’an','The Qur’an','Infidels now are they who say, "Verily God is the Messiah Ibn Maryam (son of Mary)! SAY: And who could aught obtain from God, if he chose to destroy the Messiah Ibn Maryam, and his mother, and all who are on the earth together? For with God is the sovereignty of the Heavens and of the Earth, and of all that is between them! He createth what He will; and over all things is God potent.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_ISHAQ_QURAN','ENT_ISL_ISHAQ','SRC_QURAN','The Qur’an','The Qur’an','In the earliest extant biography of Muhammad by Ibn Ishaq, we find these words addressed by Zaid, previous to the assumption of the prophetic office by Muhammad, to the Koreisch. This is one of the facts which shew that the way was to a great extent prepared for Islam. This whole address of Zaid''s-which contains not less than six passages afterwards repeated in the Koran-may be seen in Dr. Sprenger''s Life of M. p. 42.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_ISRAFIL_QURAN','ENT_ISL_ISRAFIL','SRC_QURAN','The Qur’an','The Qur’an','25 The angel Israfil. 26 Compare Sura lxxv. 16-19, p. 56. 27 It should be observed that here and in Sura vii. 19, Muhammad seems unaware of the distinction between the tree of knowledge, and the tree of life, as given in Gen. ii. 9, and iii. 5. 28 From the intensity of the light, mentioned Sura [1xxx.] xxxix. 69.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_KHIDR_QURAN','ENT_ISL_KHIDR','SRC_QURAN','The Qur’an','The Qur’an','16 The loss of our fish is a sign to us of our finding him whom we seek, namely, El-Khidr, or El-Khadir, the reputed vizier of Dhoulkarnain, and said to have drunk of the fountain of life, by virtue of which he still lives, and will live till the day of judgment. He is also said to appear, clad in green robes, to Muslims in distress, whence his name. Perhaps the name Khidr is formed from Jethro.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_MALIK_QURAN','ENT_ISL_MALIK','SRC_QURAN','The Qur’an','Quran 43:77:','Maliki yowmi-d-deen. Eyaka naboodoo, wa‚yaka nest aeen. Ihdina ''ssirat almostakeem. Sirat alezeena anhamta aleihim, gheiri-''l mughdoobi aleihim, wala dsaleen. Ameen.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_MARUT_QURAN','ENT_ISL_MARUT','SRC_QURAN','The Qur’an','The Qur’an','Sorcery did they teach to men, and what had been revealed to the two angels, Harut and Marut, at Babel. Yet no man did these two teach until they had said, "We are only a temptation. Be not then an unbeliever." From these two did men learn how to cause division between man and wife: but unless by leave of God, no man did they harm thereby.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_MUHAMMAD_QURAN','ENT_ISL_MUHAMMAD','SRC_QURAN','The Qur’an','Quran 33:40','With a change, however, in the position of Muhammad when he openly assumes the office of "public warner," the Suras begin to assume a more prosaic and didactic tone, though the poetical ornament of rhyme is preserved throughout.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISL_PROPHETS_QURAN','ENT_ISL_PROPHETS','SRC_QURAN','The Qur’an','The Qur’an','24 "The Jews, envious of Muhammad''s good reception and stay there, told him, by way of counsel, that Syria was the land of the Prophets, and that if he was really a prophet, he ought to go there." Sale from Djelal Eddin ap. Mar. Geiger, p. 12, quotes a Talmudical saying to the same effect, but without any reference. 25 A work of supererogation, and therefore doubly meritorious. Thus Tr. Berachoth, fol. 4.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISLR_ABWAB_JAHANNAM_QURAN','ENT_ISLR_ABWAB_JAHANNAM','SRC_QURAN','The Qur’an','The Qur’an','It is termed "the Opening of the Book," "the Completion," "the Sufficing Sura," the Sura of Praise, Thanks, and Prayer," "the Healer," "the Remedy," "the Basis," "the Treasure," "the Mother of the Book," "the Seven Verses of Repetition." The Muhammadans always say "Amen" after this prayer, Muhammad having been instructed, says the Sonna, to do so by the Angel Gabriel.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ISLR_DAR_AL_SALAM_QURAN','ENT_ISLR_DAR_AL_SALAM','SRC_QURAN','The Qur’an','The Qur’an','These passages may allude to the ladder set up in a tower by Wacih ben Salamah, one of the ancient doorkeepers of the Caaba, by which he professed to mount up to God and receive divine Oracles. Freyt. Einl. p. 371. 9 A community. Comp. Prov. xxx. 25, 26. Animals as well as mankind are under the control of God, are held within the limits of his decrees, are accountable to him, and will stand before him in the judgment.','J. M. Rodwell',1861,'https://www.gutenberg.org/ebooks/2800','https://quran.com/','primary-verbatim',NULL,true,'English translation (Rodwell, chronological sura order) located by name; the cited sura:ayah is the standard reference — consult the Arabic (linked).',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
